import { ethers } from 'ethers';

// Base mainnet addresses
export const CONTRACTS = {
  // Uniswap V3 on Base
  SWAP_ROUTER: '0x2626664c2603336E57B271c5C0b26F421741e481',
  QUOTER: '0x3d4e44Eb1374240CE5F1B871ab261CD16335B76a',
  FACTORY: '0x33128a8fC17869897dcE68Ed026d694621f6FDfD',
  WETH: '0x4200000000000000000000000000000000000006',
  
  // Base Sepolia testnet
  testnet: {
    SWAP_ROUTER: '0x94cC0AaC535CCDB3C01d6787D6413C739ae12bc4',
    QUOTER: '0xC5290058841028F1614F3A6F0F5816cAd0df5E27',
    FACTORY: '0x4752ba5DBc23f44D87826276BF6Fd6b1C372aD24',
    WETH: '0x4200000000000000000000000000000000000006'
  }
};

// Minimal ERC20 ABI
export const ERC20_ABI = [
  'function name() view returns (string)',
  'function symbol() view returns (string)',
  'function decimals() view returns (uint8)',
  'function totalSupply() view returns (uint256)',
  'function balanceOf(address) view returns (uint256)',
  'function transfer(address to, uint256 amount) returns (bool)',
  'function approve(address spender, uint256 amount) returns (bool)',
  'function allowance(address owner, address spender) view returns (uint256)'
];

// Uniswap V3 SwapRouter ABI (minimal)
export const SWAP_ROUTER_ABI = [
  'function exactInputSingle((address tokenIn, address tokenOut, uint24 fee, address recipient, uint256 deadline, uint256 amountIn, uint256 amountOutMinimum, uint160 sqrtPriceLimitX96)) external payable returns (uint256 amountOut)',
  'function exactOutputSingle((address tokenIn, address tokenOut, uint24 fee, address recipient, uint256 deadline, uint256 amountOut, uint256 amountInMaximum, uint160 sqrtPriceLimitX96)) external payable returns (uint256 amountIn)'
];

// Simple ERC20 Token bytecode (OpenZeppelin-based)
// This is a minimal token with name, symbol, initial supply to deployer
export const TOKEN_BYTECODE = '';

// Token factory ABI
export const TOKEN_ABI = [
  'constructor(string memory name_, string memory symbol_, uint256 initialSupply_)',
  ...ERC20_ABI
];

// Deploy a new ERC20 token
export async function deployToken(signer, name, symbol, initialSupply = '1000000000') {
  const factory = new ethers.ContractFactory(
    TOKEN_ABI,
    TOKEN_BYTECODE,
    signer
  );
  
  // Deploy with 1 billion tokens (18 decimals)
  const supply = ethers.parseEther(initialSupply);
  const contract = await factory.deploy(name, symbol, supply);
  await contract.waitForDeployment();
  
  return {
    address: await contract.getAddress(),
    name,
    symbol,
    initialSupply: supply.toString()
  };
}

// Execute a swap on Uniswap V3
export async function executeSwap(signer, tokenIn, tokenOut, amountIn, slippage = 5, testnet = false) {
  const contracts = testnet ? CONTRACTS.testnet : CONTRACTS;
  const router = new ethers.Contract(contracts.SWAP_ROUTER, SWAP_ROUTER_ABI, signer);
  
  const deadline = Math.floor(Date.now() / 1000) + 60 * 20; // 20 minutes
  const amountInWei = ethers.parseEther(amountIn.toString());
  
  // Calculate minimum output with slippage
  const amountOutMinimum = 0; // For simplicity, use 0 (real impl should quote first)
  
  const params = {
    tokenIn,
    tokenOut,
    fee: 3000, // 0.3% fee tier
    recipient: await signer.getAddress(),
    deadline,
    amountIn: amountInWei,
    amountOutMinimum,
    sqrtPriceLimitX96: 0
  };
  
  const tx = await router.exactInputSingle(params, {
    value: tokenIn === contracts.WETH ? amountInWei : 0
  });
  
  return await tx.wait();
}

// Get token info
export async function getTokenInfo(provider, tokenAddress) {
  const token = new ethers.Contract(tokenAddress, ERC20_ABI, provider);
  
  const [name, symbol, decimals, totalSupply] = await Promise.all([
    token.name(),
    token.symbol(),
    token.decimals(),
    token.totalSupply()
  ]);
  
  return { name, symbol, decimals, totalSupply: totalSupply.toString() };
}

// Get token balance
export async function getTokenBalance(provider, tokenAddress, walletAddress) {
  const token = new ethers.Contract(tokenAddress, ERC20_ABI, provider);
  const balance = await token.balanceOf(walletAddress);
  return ethers.formatEther(balance);
}
